#include "elit21/compliance/CanadaCompliance.h"
#include "elit21/util/StringUtil.h"
#include <fstream>
#include <regex>
namespace elit21 {CanadaCompliance::CanadaCompliance(std::vector<std::string>p):prohibited_(std::move(p)){}std::vector<std::string> CanadaCompliance::loadKeywords(const std::string&p){std::ifstream f(p);std::vector<std::string>v;std::string l;while(std::getline(f,l)){l=util::trim(l);if(!l.empty())v.push_back(l);}return v;}bool CanadaCompliance::validPostalCode(const std::string&v)const{static const std::regex r("^[ABCEGHJ-NPRSTVXY]\\d[ABCEGHJ-NPRSTV-Z][ -]?\\d[ABCEGHJ-NPRSTV-Z]\\d$",std::regex::icase);return std::regex_match(util::trim(v),r);}Result<void> CanadaCompliance::validateAddress(const Address&a,bool block)const{if(util::upper(a.country_code)!="CA")return Result<void>::failure("Adresse hors Canada.");if(!validPostalCode(a.postal_code))return Result<void>::failure("Code postal canadien invalide.");if(a.address1.empty()||a.city.empty()||a.province_code.empty())return Result<void>::failure("Adresse incomplète.");if(block&&(util::containsInsensitive(a.address1,"PO BOX")||util::containsInsensitive(a.address1,"C.P.")))return Result<void>::failure("Case postale interdite.");return Result<void>::success();}Result<void> CanadaCompliance::validateProduct(const std::string&t,const std::string&d)const{auto x=t+" "+d;for(auto&k:prohibited_)if(util::containsInsensitive(x,k))return Result<void>::failure("Produit bloqué par mot-clé: "+k);return Result<void>::success();}}
